<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Support Contact Form</title>
    <script src="https://unpkg.com/react@18/umd/react.development.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script src="https://cdn.tailwindcss.com"></script>
    <style>
        .form-field {
            margin-bottom: 1.5rem;
        }
        input:focus {
            outline: 2px solid #2563eb;
            outline-offset: 2px;
        }
    </style>
</head>
<body class="bg-gray-50 min-h-screen flex items-center justify-center p-4">
    <div id="root"></div>

    <script type="text/babel">
        const { useState, useRef } = React;

        const FormField = ({ id, label, type = "text", required, autocomplete, helpText, value, onChange, error, placeholder }) => {
            const helpId = helpText ? `${id}-help` : null;
            const errorId = error ? `${id}-error` : null;
            const describedBy = [helpId, errorId].filter(Boolean).join(' ') || undefined;

            return (
                <div className="form-field flex flex-col gap-1.5">
                    <label htmlFor={id} className="text-sm font-semibold text-gray-700 flex items-center gap-1">
                        {label}
                        {required && <span className="text-red-500" aria-hidden="true">*</span>}
                    </label>
                    <input
                        id={id}
                        name={id}
                        type={type}
                        required={required}
                        autoComplete={autocomplete}
                        value={value}
                        onChange={(e) => onChange(e.target.value)}
                        placeholder={placeholder}
                        aria-describedby={describedBy}
                        aria-invalid={!!error}
                        className={`w-full px-4 py-2 rounded-lg border transition-colors ${
                            error ? 'border-red-500 bg-red-50' : 'border-gray-300 focus:border-blue-500'
                        }`}
                    />
                    {helpText && (
                        <p id={helpId} className="text-xs text-gray-500">
                            {helpText}
                        </p>
                    )}
                    {error && (
                        <p id={errorId} className="text-xs text-red-600 font-medium">
                            Error: {error}
                        </p>
                    )}
                </div>
            );
        };

        const ContactForm = () => {
            const [formData, setFormData] = useState({
                fullName: '',
                email: '',
                phone: ''
            });
            const [errors, setErrors] = useState({});
            const [submitted, setSubmitted] = useState(false);
            const firstInvalidRef = useRef(null);

            const validate = () => {
                const newErrors = {};
                if (!formData.fullName.trim()) {
                    newErrors.fullName = "Full name is required.";
                }

                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                if (!formData.email.trim()) {
                    newErrors.email = "Email address is required.";
                } else if (!emailRegex.test(formData.email)) {
                    newErrors.email = "Please enter a valid email address.";
                }

                const phoneRegex = /^\+?[\d\s-()]{10,}$/;
                if (formData.phone && !phoneRegex.test(formData.phone)) {
                    newErrors.phone = "Please enter a valid phone number (at least 10 digits).";
                }

                setErrors(newErrors);
                return Object.keys(newErrors).length === 0;
            };

            const handleSubmit = (e) => {
                e.preventDefault();
                const isValid = validate();

                if (isValid) {
                    setSubmitted(true);
                    console.log('Form submitted:', formData);
                } else {
                    // Accessibility requirement: focus first invalid field
                    setTimeout(() => {
                        const firstErrorKey = Object.keys(errors)[0] || (Object.keys(validate() ? {} : validateErrors())[0]);
                        // Recalculate errors locally to find the first one immediately
                        const localErrors = {};
                        if (!formData.fullName.trim()) localErrors.fullName = true;
                        else if (!formData.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) localErrors.email = true;
                        else if (formData.phone && !/^\+?[\d\s-()]{10,}$/.test(formData.phone)) localErrors.phone = true;

                        const firstErrorId = Object.keys(localErrors)[0];
                        if (firstErrorId) {
                            document.getElementById(firstErrorId).focus();
                        }
                    }, 0);
                }
            };

            if (submitted) {
                return (
                    <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md text-center">
                        <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path>
                            </svg>
                        </div>
                        <h2 className="text-2xl font-bold text-gray-900 mb-2">Message Received!</h2>
                        <p className="text-gray-600">Thank you for reaching out. We'll get back to you soon.</p>
                        <button 
                            onClick={() => setSubmitted(false)}
                            className="mt-6 text-blue-600 font-semibold hover:underline"
                        >
                            Send another message
                        </button>
                    </div>
                );
            }

            return (
                <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md">
                    <div className="mb-8">
                        <h1 className="text-2xl font-bold text-gray-900 mb-2">Contact Support</h1>
                        <p className="text-gray-600 text-sm">Fill out the form below and we'll help you as soon as possible.</p>
                    </div>

                    <form onSubmit={handleSubmit} noValidate>
                        <FormField
                            id="fullName"
                            label="Full Name"
                            required
                            autocomplete="name"
                            value={formData.fullName}
                            onChange={(val) => setFormData({...formData, fullName: val})}
                            error={errors.fullName}
                            placeholder="John Doe"
                        />

                        <FormField
                            id="email"
                            label="Email Address"
                            type="email"
                            required
                            autocomplete="email"
                            value={formData.email}
                            onChange={(val) => setFormData({...formData, email: val})}
                            error={errors.email}
                            placeholder="john@example.com"
                        />

                        <FormField
                            id="phone"
                            label="Phone Number"
                            type="tel"
                            autocomplete="tel"
                            helpText="Format: +1 (123) 456-7890 or 123-456-7890"
                            value={formData.phone}
                            onChange={(val) => setFormData({...formData, phone: val})}
                            error={errors.phone}
                            placeholder="+1 (123) 456-7890"
                        />

                        <p className="text-xs text-gray-500 mb-6" aria-hidden="true">
                            Fields marked with <span className="text-red-500">*</span> are required.
                        </p>

                        <button
                            type="submit"
                            className="w-full bg-blue-600 text-white font-semibold py-3 px-6 rounded-lg hover:bg-blue-700 focus:outline-none focus:ring-4 focus:ring-blue-200 transition-all active:scale-[0.98]"
                        >
                            Send Message
                        </button>
                    </form>
                </div>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<ContactForm />);
    </script>
</body>
</html>
