', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-react--style-modern--validation-message-present/google/gemini-3-flash-preview__s4/index.html', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Support Contact Form</title>
    <script src="https://unpkg.com/react@18/umd/react.development.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script src="https://cdn.tailwindcss.com"></script>
    <style>
        .form-field {
            margin-bottom: 1.5rem;
        }
        input:focus {
            outline: 2px solid #2563eb;
            outline-offset: 2px;
        }
    </style>
</head>
<body class="bg-gray-50 min-h-screen flex items-center justify-center p-4">
    <div id="root"></div>

    <script type="text/babel">
        const { useState, useRef } = React;

        const FormField = ({ id, label, type = "text", required, autocomplete, helpText, value, onChange, error, placeholder }) => {
            const helpId = helpText ? `${id}-help` : null;
            const errorId = error ? `${id}-error` : null;
            const describedBy = [helpId, errorId].filter(Boolean).join(' ') || undefined;

            return (
                <div className="form-field flex flex-col gap-1.5">
                    <label htmlFor={id} className="text-sm font-semibold text-gray-700 flex items-center gap-1">
                        {label}
                        {required && <span className="text-red-500" aria-hidden="true">*</span>}
                    </label>
                    <input
                        id={id}
                        name={id}
                        type={type}
                        required={required}
                        autoComplete={autocomplete}
                        value={value}
                        onChange={(e) => onChange(e.target.value)}
                        placeholder={placeholder}
                        aria-describedby={describedBy}
                        aria-invalid={!!error}
                        className={`w-full px-4 py-2 rounded-lg border transition-colors ${
                            error ? 'border-red-500 bg-red-50' : 'border-gray-300 focus:border-blue-500'
                        }`}
                    />
                    {helpText && (
                        <p id={helpId} className="text-xs text-gray-500">
                            {helpText}
                        </p>
                    )}
                    {error && (
                        <p id={errorId} className="text-xs text-red-600 font-medium">
                            Error: {error}
                        </p>
                    )}
                </div>
            );
        };

        const ContactForm = () => {
            const [formData, setFormData] = useState({
                fullName: '',
                email: '',
                phone: ''
            });
            const [errors, setErrors] = useState({});
            const [submitted, setSubmitted] = useState(false);
            const firstInvalidRef = useRef(null);

            const validate = () => {
                const newErrors = {};
                if (!formData.fullName.trim()) {
                    newErrors.fullName = "Full name is required.";
                }

                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                if (!formData.email.trim()) {
                    newErrors.email = "Email address is required.";
                } else if (!emailRegex.test(formData.email)) {
                    newErrors.email = "Please enter a valid email address.";
                }

                const phoneRegex = /^\+?[\d\s-()]{10,}$/;
                if (formData.phone && !phoneRegex.test(formData.phone)) {
                    newErrors.phone = "Please enter a valid phone number (at least 10 digits).";
                }

                setErrors(newErrors);
                return Object.keys(newErrors).length === 0;
            };

            const handleSubmit = (e) => {
